1	import { useEffect, useRef } from "react";
2	import { Switch, Route, Router as WouterRouter, useLocation, Redirect } from "wouter";
3	import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
4	import { ClerkProvider, SignIn, SignUp, Show, useClerk } from "@clerk/react";
5	import { dark } from "@clerk/themes";
6	import { Toaster } from "@/components/ui/toaster";
7	import { TooltipProvider } from "@/components/ui/tooltip";
8	import NotFound from "@/pages/not-found";
9	import Workspace from "@/pages/workspace";
10	import WorkspaceHome from "@/pages/workspace-home";
11	import WorkspaceBySlug from "@/pages/workspace-by-slug";
12	import Account from "@/pages/account";
13	import Admin from "@/pages/admin";
14	import LearnPage from "@/pages/learn";
15	import Landing from "@/pages/landing";
16	import PublicFeedback from "@/pages/public-feedback";
17	import JoinWorkspace from "@/pages/join-workspace";
18	
19	const queryClient = new QueryClient();
20	
21	const clerkPubKey = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY;
22	const clerkProxyUrl = import.meta.env.VITE_CLERK_PROXY_URL;
23	const basePath = import.meta.env.BASE_URL.replace(/\/$/, "");
24	
25	if (!clerkPubKey) {
26	  throw new Error("Missing VITE_CLERK_PUBLISHABLE_KEY in environment");
27	}
28	
29	function stripBase(path: string): string {
30	  return basePath && path.startsWith(basePath)
31	    ? path.slice(basePath.length) || "/"
32	    : path;
33	}
34	
35	const clerkAppearance = {
36	  theme: dark,
37	  cssLayerName: "clerk",
38	  options: {
39	    logoPlacement: "inside" as const,
40	    logoLinkUrl: basePath || "/",
41	    logoImageUrl: `${typeof window !== "undefined" ? window.location.origin : ""}${basePath}/logo.svg`,
42	  },
43	  variables: {
44	    colorPrimary: "hsl(263 70% 60%)",
45	    colorForeground: "hsl(210 40% 98%)",
46	    colorMutedForeground: "hsl(215 20% 65%)",
47	    colorDanger: "hsl(0 84% 60%)",
48	    colorBackground: "hsl(222 47% 11%)",
49	    colorInput: "hsl(217 33% 17%)",
50	    colorInputForeground: "hsl(210 40% 98%)",
51	    colorNeutral: "hsl(217 33% 25%)",
52	    fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif",
53	    borderRadius: "0.5rem",
54	  },
55	  elements: {
56	    rootBox: "w-full",
57	    cardBox:
58	      "bg-[hsl(222_47%_11%)] rounded-2xl w-[440px] max-w-full overflow-hidden border border-[hsl(217_33%_25%)] shadow-2xl",
59	    card: "!shadow-none !border-0 !bg-transparent !rounded-none",
60	    footer: "!shadow-none !border-0 !bg-transparent !rounded-none",
61	    headerTitle: "text-white text-2xl font-bold",
62	    headerSubtitle: "text-slate-400",
63	    socialButtonsBlockButtonText: "text-white",
64	    formFieldLabel: "text-slate-200",
65	    footerActionLink: "text-violet-400 hover:text-violet-300",
66	    footerActionText: "text-slate-400",
67	    dividerText: "text-slate-400",
68	    identityPreviewEditButton: "text-violet-400",
69	    formFieldSuccessText: "text-emerald-400",
70	    alertText: "text-red-400",
71	    logoBox: "flex justify-center mb-2",
72	    logoImage: "h-10 w-10",
73	    socialButtonsBlockButton:
74	      "bg-[hsl(217_33%_17%)] hover:bg-[hsl(217_33%_22%)] border border-[hsl(217_33%_25%)]",
75	    formButtonPrimary:
76	      "bg-violet-600 hover:bg-violet-500 text-white font-medium",
77	    formFieldInput:
78	      "bg-[hsl(217_33%_17%)] border border-[hsl(217_33%_25%)] text-white",
79	    footerAction: "text-slate-400",
80	    dividerLine: "bg-[hsl(217_33%_25%)]",
81	    alert: "bg-red-950/40 border border-red-900",
82	    otpCodeFieldInput: "bg-[hsl(217_33%_17%)] text-white",
83	    formFieldRow: "",
84	    main: "",
85	  },
86	};
87	
88	function SignInPage() {
89	  return (
90	    <div className="flex min-h-[100dvh] items-center justify-center bg-background px-4">
91	      <SignIn
92	        routing="path"
93	        path={`${basePath}/sign-in`}
94	        signUpUrl={`${basePath}/sign-up`}
95	      />
96	    </div>
97	  );
98	}
99	
100	function SignUpPage() {
101	  return (
102	    <div className="flex min-h-[100dvh] items-center justify-center bg-background px-4">
103	      <SignUp
104	        routing="path"
105	        path={`${basePath}/sign-up`}
106	        signInUrl={`${basePath}/sign-in`}
107	      />
108	    </div>
109	  );
110	}
111	
112	function HomeRedirect() {
113	  return (
114	    <>
115	      <Show when="signed-in">
116	        <WorkspaceHome />
117	      </Show>
118	      <Show when="signed-out">
119	        <Landing />
120	      </Show>
121	    </>
122	  );
123	}
124	
125	const RESERVED_TOP_PATHS = new Set([
126	  "sign-in", "sign-up", "feedback", "account", "admin", "p", "api", "_assets", "favicon.ico", "join",
127	]);
128	
129	function ProtectedRoute({ children }: { children: React.ReactNode }) {
130	  return (
131	    <>
132	      <Show when="signed-in">{children}</Show>
133	      <Show when="signed-out">
134	        <Redirect to="/" />
135	      </Show>
136	    </>
137	  );
138	}
139	
140	function ClerkQueryClientCacheInvalidator() {
141	  const { addListener } = useClerk();
142	  const qc = useQueryClient();
143	  const prevUserIdRef = useRef<string | null | undefined>(undefined);
144	
145	  useEffect(() => {
146	    const unsubscribe = addListener(({ user }) => {
147	      const userId = user?.id ?? null;
148	      if (
149	        prevUserIdRef.current !== undefined &&
150	        prevUserIdRef.current !== userId
151	      ) {
152	        qc.clear();
153	      }
154	      prevUserIdRef.current = userId;
155	    });
156	    return unsubscribe;
157	  }, [addListener, qc]);
158	
159	  return null;
160	}
161	
162	function Routes() {
163	  return (
164	    <Switch>
165	      <Route path="/" component={HomeRedirect} />
166	      <Route path="/sign-in/*?" component={SignInPage} />
167	      <Route path="/sign-up/*?" component={SignUpPage} />
168	      <Route path="/feedback/:token" component={PublicFeedback} />
169	      <Route path="/join/:code" component={JoinWorkspace} />
170	      <Route path="/account">
171	        <ProtectedRoute>
172	          <Account />
173	        </ProtectedRoute>
174	      </Route>
175	      <Route path="/learn">
176	        <ProtectedRoute>
177	          <LearnPage />
178	        </ProtectedRoute>
179	      </Route>
180	      <Route path="/admin">
181	        <ProtectedRoute>
182	          <Admin />
183	        </ProtectedRoute>
184	      </Route>
185	      <Route path="/p/:projectId">
186	        {(params) => (
187	          <ProtectedRoute>
188	            <Workspace key={params.projectId} />
189	          </ProtectedRoute>
190	        )}
191	      </Route>
192	      <Route path="/:workspaceSlug/:projectSlug">
193	        {(params) =>
194	          RESERVED_TOP_PATHS.has(params.workspaceSlug) ? (
195	            <NotFound />
196	          ) : (
197	            <ProtectedRoute>
198	              <WorkspaceBySlug key={`${params.workspaceSlug}/${params.projectSlug}`} />
199	            </ProtectedRoute>
200	          )
201	        }
202	      </Route>
203	      <Route path="/:workspaceSlug">
204	        {(params) =>
205	          RESERVED_TOP_PATHS.has(params.workspaceSlug) ? (
206	            <NotFound />
207	          ) : (
208	            <ProtectedRoute>
209	              <WorkspaceHome key={params.workspaceSlug} />
210	            </ProtectedRoute>
211	          )
212	        }
213	      </Route>
214	      <Route component={NotFound} />
215	    </Switch>
216	  );
217	}
218	
219	function ClerkProviderWithRoutes() {
220	  const [, setLocation] = useLocation();
221	  return (
222	    <ClerkProvider
223	      publishableKey={clerkPubKey}
224	      proxyUrl={clerkProxyUrl}
225	      appearance={clerkAppearance}
226	      signInUrl={`${basePath}/sign-in`}
227	      signUpUrl={`${basePath}/sign-up`}
228	      localization={{
229	        signIn: {
230	          start: { title: "Welcome back to GameForge", subtitle: "Sign in to continue designing your game" },
231	        },
232	        signUp: {
233	          start: { title: "Join GameForge", subtitle: "Build, simulate, and ship your board game" },
234	        },
235	      }}
236	      routerPush={(to) => setLocation(stripBase(to))}
237	      routerReplace={(to) => setLocation(stripBase(to), { replace: true })}
238	    >
239	      <QueryClientProvider client={queryClient}>
240	        <ClerkQueryClientCacheInvalidator />
241	        <TooltipProvider>
242	          <Routes />
243	          <Toaster />
244	        </TooltipProvider>
245	      </QueryClientProvider>
246	    </ClerkProvider>
247	  );
248	}
249	
250	function App() {
251	  return (
252	    <WouterRouter base={basePath}>
253	      <ClerkProviderWithRoutes />
254	    </WouterRouter>
255	  );
256	}
257	
258	export default App;
259

