1	import { Link, useLocation } from "wouter";
2	import { Plus, LayoutDashboard, Activity, Gamepad2, Folder, Trash2, Settings, MoreVertical, User as UserIcon, LogOut, Shield, RotateCcw, AlertTriangle, Wand2 } from "lucide-react";
3	import { QuickStartWizard } from "@/components/wizard/quick-start-wizard";
4	// NOTE: This page is currently orphaned (no route mounts it). The real signed-in
5	// landing is workspace-home.tsx. We keep the wizard wiring here for parity if/when
6	// this page is reintroduced.
7	import { useUser, useClerk } from "@clerk/react";
8	import { useState } from "react";
9	import { useListProjects, useGetDashboardSummary, useGetRecentActivity, useCreateProject, useDeleteProject, useListTrashedProjects, useRestoreProject, usePurgeProject, getListProjectsQueryKey, getGetDashboardSummaryQueryKey, getGetRecentActivityQueryKey, getListTrashedProjectsQueryKey } from "@workspace/api-client-react";
10	import { Button } from "@/components/ui/button";
11	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
12	import { Skeleton } from "@/components/ui/skeleton";
13	import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
14	import { Input } from "@/components/ui/input";
