22	export default function Home() {
23	  const queryClient = useQueryClient();
24	  const [, setLocation] = useLocation();
25	  const { user } = useUser();
26	  const { signOut } = useClerk();
27	  const { data: projects, isLoading: projectsLoading } = useListProjects();
28	  const { data: summary, isLoading: summaryLoading } = useGetDashboardSummary();
29	  const { data: activity, isLoading: activityLoading } = useGetRecentActivity();
30	
31	  const createProject = useCreateProject();
32	  const deleteProject = useDeleteProject();
33	  const restoreProject = useRestoreProject();
34	  const purgeProject = usePurgeProject();
35	
36	  const [isCreateOpen, setIsCreateOpen] = useState(false);
37	  const [isWizardOpen, setIsWizardOpen] = useState(false);
38	  const [createData, setCreateData] = useState({ name: "", description: "", gameType: "", genre: "", playerCount: "", targetDuration: "" });
39	
40	  const [projectToDelete, setProjectToDelete] = useState<number | null>(null);
41	  const [isTrashOpen, setIsTrashOpen] = useState(false);
42	  const [projectToPurge, setProjectToPurge] = useState<number | null>(null);
43	
44	  const { data: trashedProjects, isLoading: trashedLoading } = useListTrashedProjects({
45	    query: { enabled: isTrashOpen, queryKey: getListTrashedProjectsQueryKey() },
46	  });
47	
48	  const invalidateAll = () => {
49	    queryClient.invalidateQueries({ queryKey: getListProjectsQueryKey() });
50	    queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
51	    queryClient.invalidateQueries({ queryKey: getGetRecentActivityQueryKey() });
52	    queryClient.invalidateQueries({ queryKey: getListTrashedProjectsQueryKey() });
53	  };
54	
55	  const handleRestore = async (projectId: number) => {
56	    try {
57	      await restoreProject.mutateAsync({ projectId });
58	      invalidateAll();
59	    } catch (err) {
60	      console.error(err);
61	    }
62	  };
63	
64	  const handlePurge = async () => {
65	    if (!projectToPurge) return;
66	    try {
67	      await purgeProject.mutateAsync({ projectId: projectToPurge });
68	      setProjectToPurge(null);
69	      invalidateAll();
70	    } catch (err) {
71	      console.error(err);
72	    }
73	  };
74	
75	  const handleCreate = async (e: React.FormEvent) => {
76	    e.preventDefault();
77	    if (!createData.name) return;
78	    try {
79	      const proj = await createProject.mutateAsync({ data: createData });
80	      setIsCreateOpen(false);
81	      setCreateData({ name: "", description: "", gameType: "", genre: "", playerCount: "", targetDuration: "" });
82	      queryClient.invalidateQueries({ queryKey: getListProjectsQueryKey() });
83	      queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
84	      queryClient.invalidateQueries({ queryKey: getGetRecentActivityQueryKey() });
85	      setLocation(`/p/${proj.id}`);
86	    } catch (err) {
87	      console.error(err);
88	    }
89	  };
90	
91	  const handleDelete = async () => {
92	    if (!projectToDelete) return;
93	    try {
94	      await deleteProject.mutateAsync({ projectId: projectToDelete });
95	      setProjectToDelete(null);
96	      queryClient.invalidateQueries({ queryKey: getListProjectsQueryKey() });
97	      queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
98	      queryClient.invalidateQueries({ queryKey: getGetRecentActivityQueryKey() });
99	    } catch (err) {
100	      console.error(err);
101	    }
102	  };
103	
104	  return (
105	    <div className="min-h-screen bg-background text-foreground flex flex-col items-center">
106	      <div className="w-full max-w-6xl p-8 flex flex-col gap-8">
107	        <div className="flex items-center justify-between">
108	          <div>
109	            <h1 className="text-4xl font-bold tracking-tight text-primary flex items-center gap-3">
110	              <Gamepad2 className="h-10 w-10" /> GameForge
111	            </h1>
112	            <p className="text-muted-foreground mt-2 text-lg">Your AI-powered board game design studio.</p>
113	          </div>
114	          <div className="flex items-center gap-3">
115	            <Button variant="outline" size="lg" className="gap-2" onClick={() => setIsTrashOpen(true)}>
