127	            <DialogContent className="sm:max-w-[425px]">
128	              <DialogHeader>
129	                <DialogTitle>Create New Project</DialogTitle>
130	                <DialogDescription>
131	                  Start a new board game design project. You can change these details later.
132	                </DialogDescription>
133	              </DialogHeader>
134	              <form onSubmit={handleCreate} className="space-y-4 py-4">
135	                <div className="space-y-2">
136	                  <Label htmlFor="name">Name *</Label>
137	                  <Input id="name" value={createData.name} onChange={e => setCreateData({ ...createData, name: e.target.value })} placeholder="e.g. Settlers of Catan" autoFocus required />
138	                </div>
139	                <div className="space-y-2">
140	                  <Label htmlFor="description">Description</Label>
141	                  <Textarea id="description" value={createData.description} onChange={e => setCreateData({ ...createData, description: e.target.value })} placeholder="A game about trading and building..." />
142	                </div>
143	                <div className="grid grid-cols-2 gap-4">
144	                  <div className="space-y-2">
