190	              </DropdownMenuContent>
191	            </DropdownMenu>
192	          </div>
193	        </div>
194	
195	        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
196	          <Card className="bg-card border-card-border">
197	            <CardHeader className="pb-2">
198	              <CardTitle className="text-sm font-medium text-muted-foreground flex items-center gap-2">
199	                <Folder className="h-4 w-4" /> Total Projects
