253	                {[1, 2, 3, 4].map((i) => <Skeleton key={i} className="h-40 w-full" />)}
254	              </div>
255	            ) : projects && projects.length > 0 ? (
256	              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
257	                {projects.map((project) => (
258	                  <Card
259	                    key={project.id}
260	                    role="link"
261	                    tabIndex={0}
262	                    onClick={() => setLocation(`/p/${project.id}`)}
263	                    onKeyDown={(e) => {
264	                      if (e.key === "Enter" || e.key === " ") {
265	                        e.preventDefault();
266	                        setLocation(`/p/${project.id}`);
