267	function useWorkspacesList() {
268	  const [workspaces, setWorkspaces] = useState<Workspace[] | null>(null);
269	  const [error, setError] = useState<string | null>(null);
270	  const reload = async () => {
271	    try {
272	      const list = await workspacesApi.list();
273	      setWorkspaces(list);
274	    } catch (err) {
275	      setError(err instanceof Error ? err.message : String(err));
276	    }
277	  };
278	  useEffect(() => { reload(); }, []);
279	  return { workspaces, error, reload };
280	}
