149	      if (raw) {
150	        const draft = JSON.parse(raw) as Partial<WizardAnswers>;
151	        setAnswers(prev => ({ ...prev, ...draft }));
152	      }
153	    } catch { /* ignore */ }
154	  }, [open]);
155	
156	  // Save draft on change
157	  useEffect(() => {
158	    if (!open || generating) return;
159	    try { sessionStorage.setItem(STORAGE_KEY, JSON.stringify(answers)); } catch { /* ignore */ }
160	  }, [answers, open, generating]);
161	
162	  // Reset step when reopened
163	  useEffect(() => {
164	    if (open) {
165	      setStep(0);
166	      setDirection(1);
167	      setStages([]);
168	      setGenerating(false);
169	    }
170	  }, [open]);
171	
172	  const isLast = step === STEPS.length - 1;
173	  const currentStep = STEPS[step]!;
174	  const progress = ((step + 1) / STEPS.length) * 100;
175	
176	  const canAdvance = useMemo(() => {
177	    if (step === 0) {
178	      if (!answers.theme) return false;
179	      if (answers.theme === "other" && !answers.customTheme.trim()) return false;
180	      return true;
181	    }
182	    return true;
183	  }, [step, answers]);
184	
185	  const goNext = () => {
186	    if (!canAdvance) return;
187	    if (isLast) {
188	      void handleCreate();
189	      return;
190	    }
191	    setDirection(1);
192	    setStep(s => Math.min(s + 1, STEPS.length - 1));
193	  };
194	
195	  const goBack = () => {
196	    setDirection(-1);
197	    setStep(s => Math.max(s - 1, 0));
198	  };
199	
200	  const playerCountString = (n: number) => n === 1 ? "1 (solo)" : `${n} players`;
201	  const playTimeString = (mins: number) => mins >= 60
202	    ? `${Math.floor(mins / 60)}h${mins % 60 ? ` ${mins % 60}m` : ""}`
203	    : `${mins} min`;
204	
205	  const themeForPrompt = answers.theme === "other"
206	    ? answers.customTheme.trim()
207	    : answers.themeFlavor;
208	
209	  const updateStage = (id: string, status: GenStatus) => {
210	    setStages(prev => prev.map(s => s.id === id ? { ...s, status } : s));
211	  };
212	
213	  const handleCreate = async () => {
214	    setGenerating(true);
215	    const complexity = COMPLEXITIES.find(c => c.id === answers.complexity)!;
216	    const themeLabel = answers.theme === "other"
217	      ? answers.customTheme.trim()
218	      : THEMES.find(t => t.id === answers.theme)?.label ?? "custom";
219	    const projectName = answers.pitch.trim()
220	      ? answers.pitch.trim().slice(0, 60)
221	      : `My ${themeLabel} game`;
222	
223	    const initialStages: GenStage[] = [
224	      { id: "project",   label: "Creating your project...",       status: "running" },
225	      { id: "entities",  label: `Designing ${complexity.componentCount} components...`, status: "pending" },
226	      { id: "players",   label: "Setting up player roles...",     status: "pending" },
227	      { id: "rules",     label: `Drafting ${complexity.ruleCount} starter rules...`,  status: "pending" },
228	    ];
229	    setStages(initialStages);
230	
231	    let projectId: number | null = null;
232	    let navigateTo = "";
233	
234	    const projectBody = {
235	      name: projectName,
236	      description: answers.pitch.trim() || `A ${complexity.label.toLowerCase()} ${themeLabel.toLowerCase()} game for ${playerCountString(answers.playerCount)}.`,
237	      gameType: complexity.label,
238	      genre: themeLabel,
239	      playerCount: String(answers.playerCount),
240	      targetDuration: playTimeString(answers.playTime),
241	    };
242	
243	    try {
244	      // Step 1: Create the project (workspace-scoped if a slug was provided)
245	      if (workspaceSlug) {
246	        const out = await workspacesApi.createProject(workspaceSlug, projectBody);
247	        projectId = out.project.id;
248	        navigateTo = `/${out.workspaceSlug}/${out.project.slug ?? out.project.id}`;
249	      } else {
250	        const proj = await createProject.mutateAsync({ data: projectBody });
251	        projectId = proj.id;
252	        navigateTo = `/p/${proj.id}`;
253	      }
254	      updateStage("project", "done");
255	
256	      // Step 2: Generate components, players, rules in parallel
257	      const contextSummary = [
258	        themeForPrompt,
259	        `for ${playerCountString(answers.playerCount)}`,
260	        `~${playTimeString(answers.playTime)}`,
261	        `${complexity.label.toLowerCase()} complexity`,
262	        answers.pitch.trim() ? `Pitch: ${answers.pitch.trim()}` : "",
263	      ].filter(Boolean).join(", ");
264	
265	      const entitiesPrompt =
266	        `Generate ${complexity.componentCount} starter game components for a ${contextSummary}. ` +
267	        `Mix component types (cards, tokens, boards, dice, tiles) appropriate for the theme. ` +
268	        `Each should have a clear name, type, and 1-sentence description.`;
269	
270	      const playersPrompt =
271	        `Generate 2 distinct player roles or archetypes for a ${contextSummary}. ` +
272	        `Each role should have a name, a clear strategic identity, and a short description of how they play differently.`;
273	
274	      const rulesPrompt =
275	        `Generate ${complexity.ruleCount} starter rules for a ${contextSummary}. ` +
276	        `Include: a basic win condition, a turn-structure rule, and ${complexity.ruleCount - 2} core mechanic rules. ` +
277	        `Each rule should have a clear title and 1-2 sentence content.`;
278	
279	      updateStage("entities", "running");
280	      updateStage("players", "running");
281	      updateStage("rules", "running");
282	
283	      const [entitiesRes, playersRes, rulesRes] = await Promise.allSettled([
284	        aiGenerateEntities.mutateAsync({ projectId, data: { prompt: entitiesPrompt, count: complexity.componentCount } })
285	          .then(r => { updateStage("entities", "done"); return r; })
286	          .catch(e => { updateStage("entities", "failed"); throw e; }),
287	        aiGeneratePlayers.mutateAsync({ projectId, data: { prompt: playersPrompt, count: 2 } })
288	          .then(r => { updateStage("players", "done"); return r; })
289	          .catch(e => { updateStage("players", "failed"); throw e; }),
290	        aiGenerateRules.mutateAsync({ projectId, data: { prompt: rulesPrompt, count: complexity.ruleCount } })
291	          .then(r => { updateStage("rules", "done"); return r; })
292	          .catch(e => { updateStage("rules", "failed"); throw e; }),
293	      ]);
294	
295	      const allFailed = [entitiesRes, playersRes, rulesRes].every(r => r.status === "rejected");
296	      if (allFailed) {
297	        toast({
298	          title: "AI generation failed",
299	          description: "Your project was created, but no content was generated. You can add content manually.",
300	          variant: "destructive",
301	        });
302	      } else {
303	        const failedCount = [entitiesRes, playersRes, rulesRes].filter(r => r.status === "rejected").length;
304	        if (failedCount > 0) {
305	          toast({
306	            title: `Project created with ${3 - failedCount} of 3 sections`,
307	            description: "Some AI generation steps failed. You can retry them inside the workspace.",
308	          });
309	        } else {
310	          toast({ title: "Game ready!", description: "Your skeleton is set up — let's play." });
311	        }
312	      }
313	
314	      try { sessionStorage.removeItem(STORAGE_KEY); } catch { /* ignore */ }
315	
316	      // Invalidate caches so the new project shows up
317	      queryClient.invalidateQueries({ queryKey: getListProjectsQueryKey() });
318	      queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
319	      queryClient.invalidateQueries({ queryKey: getGetRecentActivityQueryKey() });
320	      onCreated?.();
321	
322	      // Tiny delay so the user can see all green checks
323	      scheduleNavigate(navigateTo);
324	    } catch (err) {
325	      // Project creation itself failed
326	      if (!projectId) {
327	        updateStage("project", "failed");
328	        toast({
329	          title: "Couldn't create project",
330	          description: err instanceof Error ? err.message : String(err),
331	          variant: "destructive",
332	        });
333	        if (isMountedRef.current) setGenerating(false);
334	      } else {
335	        // Project exists, AI failed — still navigate
336	        scheduleNavigate(navigateTo);
337	      }
338	    }
339	  };
340	
341	  return (
342	    <Dialog open={open} onOpenChange={(o) => { if (!generating) onOpenChange(o); }}>
343	      <DialogContent className="sm:max-w-[640px] p-0 overflow-hidden">
344	        <DialogHeader className="px-6 pt-6 pb-4 border-b border-border bg-gradient-to-br from-primary/5 to-transparent">
345	          <DialogTitle className="flex items-center gap-2 text-2xl">
346	            <Wand2 className="w-6 h-6 text-primary" />
347	            Quick Start Wizard
348	          </DialogTitle>
349	          <DialogDescription>
350	            {generating
351	              ? "Hang tight — building your starter game..."
352	              : "Welcome! Let's design your first game in 5 minutes."}
353	          </DialogDescription>
354	          {!generating && (
355	            <div className="pt-2 space-y-1.5">
356	              <div className="flex items-center justify-between text-xs text-muted-foreground">
357	                <span>Step {step + 1} of {STEPS.length}</span>
358	                <span>{Math.round(progress)}%</span>
359	              </div>
360	              <Progress value={progress} className="h-1.5" />
361	            </div>
362	          )}
363	        </DialogHeader>
364	
365	        <div className="px-6 py-6 min-h-[380px]">
366	          {generating ? (
367	            <GenerationStatus stages={stages} />
368	          ) : (
369	            <AnimatePresence mode="wait" custom={direction}>
370	              <motion.div
371	                key={currentStep.id}
372	                custom={direction}
373	                initial={{ opacity: 0, x: direction * 30 }}
374	                animate={{ opacity: 1, x: 0 }}
375	                exit={{ opacity: 0, x: direction * -30 }}
376	                transition={{ duration: 0.2 }}
377	              >
378	                <div className="space-y-1 mb-5">
379	                  <h3 className="text-xl font-semibold text-foreground">{currentStep.title}</h3>
380	                  <p className="text-sm text-muted-foreground">{currentStep.subtitle}</p>
381	                </div>
382	
383	                {currentStep.id === "theme" && (
384	                  <ThemeStep
385	                    selectedId={answers.theme}
386	                    customTheme={answers.customTheme}
387	                    onSelect={(theme) => setAnswers(a => ({ ...a, theme: theme.id, themeFlavor: theme.flavor }))}
388	                    onCustomChange={(v) => setAnswers(a => ({ ...a, customTheme: v }))}
389	                  />
390	                )}
391	
392	                {currentStep.id === "players" && (
393	                  <SliderStep
394	                    value={answers.playerCount}
395	                    min={1}
396	                    max={8}
397	                    step={1}
398	                    display={playerCountString(answers.playerCount)}
399	                    bigDisplay={String(answers.playerCount)}
400	                    bigSubtitle={answers.playerCount === 1 ? "solo" : answers.playerCount <= 2 ? "duel / 2P" : answers.playerCount <= 4 ? "small group" : "party"}
401	                    onChange={(v) => setAnswers(a => ({ ...a, playerCount: v }))}
402	                  />
403	                )}
404	
405	                {currentStep.id === "time" && (
406	                  <SliderStep
407	                    value={answers.playTime}
408	                    min={15}
409	                    max={120}
410	                    step={15}
411	                    display={playTimeString(answers.playTime)}
412	                    bigDisplay={playTimeString(answers.playTime)}
413	                    bigSubtitle={answers.playTime <= 30 ? "quick play" : answers.playTime <= 60 ? "casual session" : answers.playTime <= 90 ? "main event" : "epic"}
414	                    onChange={(v) => setAnswers(a => ({ ...a, playTime: v }))}
415	                  />
416	                )}
417	
418	                {currentStep.id === "complexity" && (
419	                  <ComplexityStep
420	                    selectedId={answers.complexity}
421	                    onSelect={(id) => setAnswers(a => ({ ...a, complexity: id }))}
422	                  />
423	                )}
424	
425	                {currentStep.id === "pitch" && (
426	                  <PitchStep
427	                    value={answers.pitch}
428	                    onChange={(v) => setAnswers(a => ({ ...a, pitch: v }))}
429	                  />
430	                )}
431	              </motion.div>
432	            </AnimatePresence>
433	          )}
434	        </div>
435	
436	        {!generating && (
437	          <div className="px-6 py-4 border-t border-border flex items-center justify-between bg-muted/20">
438	            <Button
439	              variant="ghost"
440	              onClick={goBack}
441	              disabled={step === 0}
442	              className="gap-1"
443	            >
444	              <ChevronLeft className="w-4 h-4" />
445	              Back
446	            </Button>
447	            <Button
448	              onClick={goNext}
449	              disabled={!canAdvance}
450	              className="gap-1"
451	              data-testid="wizard-next"
452	            >
453	              {isLast ? (
454	                <>
455	                  <Sparkles className="w-4 h-4" />
456	                  Create my game
457	                </>
458	              ) : (
459	                <>
460	                  Next
461	                  <ChevronRight className="w-4 h-4" />
462	                </>
463	              )}
464	            </Button>
465	          </div>
466	        )}
467	      </DialogContent>
468	    </Dialog>
469	  );
470	}
