474	function ThemeStep({
475	  selectedId, customTheme, onSelect, onCustomChange,
476	}: {
477	  selectedId: string;
478	  customTheme: string;
479	  onSelect: (theme: Theme) => void;
480	  onCustomChange: (v: string) => void;
481	}) {
482	  return (
483	    <div className="space-y-3">
484	      <div className="grid grid-cols-2 gap-2.5">
485	        {THEMES.map((theme) => {
486	          const Icon = theme.icon;
487	          const isSelected = selectedId === theme.id;
488	          return (
489	            <button
490	              key={theme.id}
491	              type="button"
492	              onClick={() => onSelect(theme)}
493	              className={`flex items-start gap-3 p-3 rounded-lg border text-left transition-all ${
494	                isSelected
495	                  ? "border-primary bg-primary/10 ring-1 ring-primary/30"
496	                  : "border-border bg-muted/10 hover:border-primary/40 hover:bg-muted/20"
497	              }`}
498	              data-testid={`theme-${theme.id}`}
499	            >
500	              <Icon className={`w-5 h-5 shrink-0 mt-0.5 ${isSelected ? "text-primary" : "text-muted-foreground"}`} />
