503	                <div className="text-xs text-muted-foreground">{theme.description}</div>
504	              </div>
505	              {isSelected && <Check className="w-4 h-4 text-primary shrink-0 ml-auto" />}
506	            </button>
507	          );
508	        })}
509	      </div>
510	      {selectedId === "other" && (
511	        <div className="space-y-1.5 pt-2">
512	          <Label htmlFor="custom-theme" className="text-xs">Describe your setting</Label>
513	          <Input
514	            id="custom-theme"
515	            value={customTheme}
516	            onChange={(e) => onCustomChange(e.target.value)}
517	            placeholder="e.g. cyberpunk noir, post-apocalyptic farming, etc."
518	            autoFocus
519	            data-testid="custom-theme-input"
520	          />
521	        </div>
522	      )}
523	    </div>
524	  );
525	}
